"""严格Triton hardswish_out。复用本批已核验hardswish的完整块流式设备核，
连续输出直接写入调用方out，避免创建中间结果；真实stride分支由Triton复制。
保留NaN/Inf、负零及当前stream；缓存区分输入/输出dtype、设备与大小。

定点：clamp 是 HIVM 上的主要开销，``tl.minimum/tl.maximum`` 各展开成五条
向量指令（cmp+not+min+select+select）。改用单条 libdevice ``relu`` 的等价式
``clamp(x+3,0,6) == 6 - relu(6 - relu(x+3))``，每元素指令数约减半；fp32 求值
保持不变（16 位求值在 x=-3 附近漂移超过 1e-4），靠 multibuffer 与更宽 tile
消化额外 UB 占用。
"""

import torch
import torch_npu
import triton
import triton.language as tl
from triton.language.extra.cann import libdevice as _ld

_STREAM = {}
_PLANS = {}
_EMPTY_LIKE = torch.empty_like
# dtype, n, device, launch, grid, block, opts, fn, packed, getter, has_launch, out_dtype, mb, fast
_FAST = [None, -1, -1, None, 1, 4096, {}, None, None, None, False, None, False, False]


@triton.jit
def _hardswish_stream(X, Y, N: tl.constexpr, BLOCK: tl.constexpr, FAST: tl.constexpr):
    pid = tl.program_id(0)
    lane = tl.arange(0, BLOCK)
    step = tl.num_programs(0) * BLOCK
    full = (N // step) * step
    for start in range(pid * BLOCK, full, step):
        x = tl.load(X + start + lane).to(tl.float32)
        if FAST:
            t = x + 3.0
            inner = tl.where(t < 6.0, _ld.relu(t), 6.0)
        else:
            inner = 6.0 - _ld.relu(6.0 - _ld.relu(x + 3.0))
        tl.store(Y + start + lane, (x * inner * (1.0 / 6.0)).to(Y.dtype.element_ty))
    offset = full + pid * BLOCK + lane
    valid = offset < N
    x = tl.load(X + offset, valid, other=0).to(tl.float32)
    if FAST:
        t = x + 3.0
        inner = tl.where(t < 6.0, _ld.relu(t), 6.0)
    else:
        inner = 6.0 - _ld.relu(6.0 - _ld.relu(x + 3.0))
    tl.store(Y + offset, (x * inner * (1.0 / 6.0)).to(Y.dtype.element_ty), valid)


def _stream_getter(device):
    getter = _STREAM.get(device)
    if getter is not None:
        return getter
    raw = getattr(torch_npu._C, "_npu_getCurrentRawStreamNoWait", None)
    if raw is not None:
        try:
            expected = int(torch.npu.current_stream(device).npu_stream)
            try:
                if int(raw(device)) == expected:
                    getter = lambda: raw(device)
            except TypeError:
                if int(raw()) == expected:
                    getter = raw
        except Exception:
            getter = None
    if getter is None:
        from triton.runtime import driver

        getter = lambda: driver.active.get_current_stream(device)
    _STREAM[device] = getter
    return getter


def _vector_cores(device):
    """Concurrency cap: reported vector-core count, else work-derived."""
    try:
        from triton.runtime import driver

        props = driver.active.utils.get_device_properties(device)
        cores = int(props.get("num_vectorcore") or 0)
        if cores > 0:
            return cores
    except Exception:
        pass
    return 0


def _geometry(n, device, dtype):
    """Pick (block, grid, multibuffer, fast_clamp); return candidates, best first.

    Same measured table as ``hardswish``: fp32 evaluation needs the 8192-lane
    cap, small shapes prefer many short programs over one 4096-lane program,
    and the one-relu-plus-select clamp wins for 16-bit inputs up to 2^24.
    """
    fast = dtype is not torch.float32 and n <= 1 << 24
    if n <= 8192:
        block = min(1024, max(32, 1 << (n - 1).bit_length()))
        return [(block, (n + block - 1) // block, False, fast)]
    if n < 131072:
        block = 4096
        return [(block, (n + block - 1) // block, True, fast)]
    cores = _vector_cores(device)
    cdiv = (n + 8191) // 8192
    grid = min(cores, cdiv) if cores else min(cdiv, 65535)
    return [(8192, grid, True, fast), (4096, grid, True, fast)]


def _build(y, out, n, device):
    """Compile this specialization once and return its launch plan."""
    launch = fn = packed = stream = None
    block = grid = 0
    mb = fast = False
    for block, grid, mb, fast in _geometry(n, device, y.dtype):
        try:
            compiled = _hardswish_stream.warmup(
                y, out, n, block, fast, grid=(1,), multibuffer=mb
            )
            launcher = compiled.run
            if (
                getattr(launcher, "compile_only", False)
                or getattr(launcher, "enable_msprof_register_tensor", False)
                or getattr(launcher.metadata, "debug_enabled", False)
                or getattr(launcher.metadata, "debug", False)
            ):
                continue
            launch = launcher.launch
            fn = compiled.function
            packed = compiled.packed_metadata
            stream = _stream_getter(device)
            break
        except Exception:
            launch = None
    return [
        y.dtype,
        n,
        device,
        launch,
        grid,
        block,
        {},
        fn,
        packed,
        stream,
        launch is not None,
        out.dtype,
        mb,
        fast,
    ]


def _slow(y, out, n):
    if not n:
        return
    device = y.get_device()
    key = (device, y.dtype, out.dtype, n)
    plan = _PLANS.get(key)
    if plan is None:
        plan = _PLANS[key] = _build(y, out, n, device)
    _FAST[:] = plan
    plan[0], plan[1], plan[2] = y.dtype, n, device
    if n:
        _hardswish_stream[plan[4],](y, out, n, plan[5], plan[13], multibuffer=plan[12])


def run(x, out):
    # out仅调整元数据/存储，不执行宿主数值或复制。
    if out.shape != x.shape:
        out.resize_(x.shape)
    device = x.get_device()
    if out.get_device() != device:
        raise ValueError("输入和out必须位于同一设备")
    if not x.is_contiguous():
        x = _strict_clone(x)
    n = x.numel()
    if not out.is_contiguous():
        temporary = torch.empty_like(x, dtype=out.dtype)
        _slow(x, temporary, n)
        _strict_copy_into(out, temporary)
        return out
    f = _FAST
    if x.dtype is f[0] and out.dtype is f[11] and n == f[1] and device == f[2]:
        xp = x.data_ptr()
        yp = out.data_ptr()
        if f[10] and not ((xp | yp) & 15):
            try:
                f[3](
                    f[4],
                    1,
                    1,
                    f[9](),
                    f[7],
                    f[8],
                    None,
                    None,
                    None,
                    xp,
                    yp,
                    n,
                    f[5],
                    f[13],
                )
            except Exception:
                _slow(x, out, n)
        elif n:
            _hardswish_stream[f[4],](x, out, n, f[5], f[13], multibuffer=f[12])
        return out
    _slow(x, out, n)
    return out


@triton.jit
def _strict_copy_kernel(
    X,
    Y,
    N: tl.constexpr,
    SHAPE: tl.constexpr,
    XS: tl.constexpr,
    YS: tl.constexpr,
    BLOCK: tl.constexpr,
):
    i = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    remain = i
    xp = tl.full((BLOCK,), 0, tl.int64)
    yp = tl.full((BLOCK,), 0, tl.int64)
    for d in tl.static_range(len(SHAPE) - 1, -1, -1):
        coord = remain % SHAPE[d]
        remain = remain // SHAPE[d]
        xp += coord * XS[d]
        yp += coord * YS[d]
    value = tl.load(X + xp, i < N, other=0)
    tl.store(Y + yp, value, i < N)


@triton.jit
def _strict_fill_kernel(Y, N: tl.constexpr, VALUE: tl.constexpr, BLOCK: tl.constexpr):
    i = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    tl.store(Y + i, VALUE, i < N)


@triton.jit
def _strict_random_kernel(Y, N: tl.constexpr, SEED, OFFSET, BLOCK: tl.constexpr):
    i = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    # 备用随机采样路径；全部随机数计算在Triton内，生成器仅在宿主管理状态。
    value = tl.rand(SEED, (i.to(tl.uint64) + OFFSET).to(tl.uint32))
    tl.store(Y + i, value, i < N)


def _strict_empty_like(x, *, dtype=None, **kwargs):
    return torch.empty(
        tuple(x.shape), device=x.device, dtype=x.dtype if dtype is None else dtype
    )


def _strict_copy_into(dst, src):
    if tuple(dst.shape) != tuple(src.shape):
        raise ValueError("strict copy requires equal shapes")
    if dst.numel():
        _strict_copy_kernel[(triton.cdiv(dst.numel(), 1024),)](
            src,
            dst,
            dst.numel(),
            tuple(dst.shape),
            tuple(src.stride()),
            tuple(dst.stride()),
            1024,
        )
    return dst


def _strict_clone(x, **kwargs):
    return _strict_copy_into(_strict_empty_like(x), x)


def _strict_contiguous(x, *args, **kwargs):
    return x if x.is_contiguous() else _strict_clone(x)


def _strict_cast(x, dtype):
    if dtype == x.dtype:
        return x
    return _strict_copy_into(_strict_empty_like(x, dtype=dtype), x)


def _strict_reshape(x, *shape):
    # view只操作元数据，输入连续化由上面的Triton复制完成。
    return _strict_contiguous(x).view(*shape)


def _strict_flatten(x, start_dim=0, end_dim=-1):
    rank = x.ndim
    first = start_dim % rank
    last = end_dim % rank
    size = 1
    for n in x.shape[first : last + 1]:
        size *= n
    shape = tuple(x.shape[:first]) + (size,) + tuple(x.shape[last + 1 :])
    return _strict_contiguous(x).view(shape)


def _strict_full(shape, value, **kwargs):
    if isinstance(shape, int):
        shape = (shape,)
    out = torch.empty(shape, **kwargs)
    if out.numel():
        _strict_fill_kernel[(triton.cdiv(out.numel(), 1024),)](
            out, out.numel(), value, 1024
        )
    return out


def _strict_zeros(*shape, **kwargs):
    shape = shape[0] if len(shape) == 1 else shape
    return _strict_full(shape, 0, **kwargs)


def _strict_ones(*shape, **kwargs):
    shape = shape[0] if len(shape) == 1 else shape
    return _strict_full(shape, 1, **kwargs)


def _strict_rand(*shape, **kwargs):
    shape = shape[0] if len(shape) == 1 else shape
    generator = kwargs.pop("generator", None)
    out = torch.empty(shape, **kwargs)
    if out.numel():
        if generator is None:

            generator = torch.npu.default_generators[out.device.index or 0]
        seed = generator.initial_seed()
        offset = generator.get_offset()
        advance = triton.cdiv(out.numel(), 4) * 4
        if offset + advance >= 2**32:
            raise RuntimeError("备用随机路径超过32位计数范围，明确拒绝而非静默重复")
        generator.set_offset(offset + advance)
        _strict_random_kernel[(triton.cdiv(out.numel(), 256),)](
            out, out.numel(), seed, offset, 256
        )
    return out


